// TH14 弹型合成映射（见 transcribe/th14/touhou-bullets.ecl）；本卡只用源 type10。
// 源 type0-23 对应目标同号，24-42 对应目标 +1；此处数值为目标逻辑行基址。
const TH14_SHARD: int = 512;

// TH14 Stage 5 道中 th14_s5_w10
// 源：st05.ecl.txt MainSub06 本地入口 844-869（两批各 10 只 ECir00，排程 360 帧）。
// 卡帧 0 = 入口；OPENING_BUFFER 后按源排程出怪（源第一批 0 起、第二批 260 起，间 10）。

const TIME_LIMIT: int = 1624;
const OPENING_BUFFER: int = 120;
const ECIR_WAVES: int = 3;   // 源 ECir00_at 的 $B = $I0 = 3 波
const WAVE_GAP: int = 4;     // 源每波 etOn 后 wait(4)

xformdef ECIR_ACCEL(gx: fx, gy: fx) {
    // 源 etEx type4 ACCEL：a=120、r=0.033333335、s=F2-pi；进入时定方向，到期清两轴。
    @120 set_gravity(gx, gy);
    set_gravity(0fx, 0fx);
}

async sub ecir_attack(f2: angle) {
    wait(10);                                  // 源 ECir00_at 首 wait(10)
    var n: int = 1 + 2 * global(GVAR_RANK);    // 源难度计数 !E/!N/!H/!LO = 1/3/5/7
    var gdir: angle = f2 - 180deg;             // 源 ACCEL 的 s = F2 - pi
    var gx: fx = 0.033333335fx * cos(gdir);
    var gy: fx = 0.033333335fx * sin(gdir);
    for wave in 0..ECIR_WAVES {
        // 源每波一次 RANDF2*10deg，整波共享同一基准角
        var base: angle = f2 + (rand(1820) as angle);
        for i in 0..n {
            // 源 etAim(0,1) 固定方向 fan：0, -d, +d, -2d, +2d, ... (d = 10deg)
            var off: int = ((i + 1) / 2) * 1820;
            if i % 2 != 0 { off = 0 - off; }
            var a: angle = base + (off as angle);
            var vx: fx = 2fx * cos(a);
            var vy: fx = 2fx * sin(a);
            // 出生 ANIM 退位移 position -= 4*velocity（按实际弹角与初速）；出生减速/无判定按已批准口径省略
            _ = fire(TH14_SHARD, 6, $self_x - 4fx * vx, $self_y - 4fx * vy,
                     2fx, a, ECIR_ACCEL(gx, gy), none);
        }
        wait(WAVE_GAP);
    }
}

async sub ecir(f0: fx, f1: fx, f2: angle) {
    set_invuln(65535);
    set_hurtbox(12fx);   // 源 setHurtbox(24,24)，普通圆形取第一值 x0.5
    set_hitbox(8fx);     // 源 setHitbox(16,16)
    set_enemy_flag(ENEMY_NO_BODY, 1);   // 源 flagSet(15) 含体碰屏蔽（入口 160 帧）

    var sx: fx = $self_x;
    var sy: fx = $self_y;
    var ux: fx = (rand(16384) as fx) / 16384fx;
    var uy: fx = (rand(16384) as fx) / 16384fx;
    // 源 402 REL=(160+U*32, U*64)；403 160 帧 mode1(t^2) 插值到 (F0,F1)
    move_to(0, sx + 160fx + ux * 32fx, sy + uy * 64fx, EASE_LINEAR);
    move_to(160, sx + f0, sy + f1, EASE_QUAD_IN);
    wait(160);
    set_enemy_flag(ENEMY_NO_BODY, 0);   // 源 flagClear(15)
    spawn ecir_attack(f2);
    wait(120);
    // 源 moveVel(ANGLE_PLAYER,0) + moveSpeedTime(120,0,3.0)：角度即定，速率线性到 3
    move_angle(0, aim_player(), EASE_LINEAR);
    move_speed(120, 3fx, EASE_LINEAR);
    loop { wait(1000); }   // 源 ECir00_836 轮询 wait(1000)，出界由引擎回收
}

async sub wave_pattern() {
    wait(OPENING_BUFFER);
    // 源 844-855：第一批 F0 从 -160 每只 +32（创建值 -128..160），F1=RANDF2*32，出生 (0,360)
    var i1: int = 0;
    while i1 < 10 {
        var fa: fx = -160fx + 32fx * (i1 + 1);
        var ua: fx = (rand(16384) as fx) / 16384fx;
        _ = spawn_enemy(0fx, 360fx, 160, 0, 1000, 0, ecir(fa, ua * 32fx, 90deg));
        wait(10);
        i1 = i1 + 1;
    }
    wait(160);   // 源 856
    // 源 857-869：第二批 F0 从 160 每只 -32（创建值 128..-160），F1=RANDF2*32-64，
    // F2=±pi/2 创建后逐只翻号（首只 +），出生 (0,300)
    var i2: int = 0;
    while i2 < 10 {
        var fb: fx = 160fx - 32fx * (i2 + 1);
        var ub: fx = (rand(16384) as fx) / 16384fx;
        var f2b: angle = 90deg;
        if i2 % 2 != 0 { f2b = -90deg; }
        _ = spawn_enemy(0fx, 300fx, 160, 0, 1000, 0, ecir(fb, ub * 32fx - 64fx, f2b));
        wait(10);
        i2 = i2 + 1;
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
